const payload = $input.first().json.body || $input.first().json;

const maleVoices = ['TX3LPaxmHKxFdv7VOQHJ','nPczCjzI2devNBz1zQrb','IKne3meq5aSn9XLyUdCD','CwhRBWXzGAHq8TQ4Fs17','cjVigY5qzO86Huf0OWal'];
const femaleVoices = ['FGY2WhTYpPnrIDTdsKH5','cgSgspJ2msm6clMCkdW9','XrExE9yKIg1WjnnlVkGX','Xb7hH8MSUJpSbSDYk0k2','hpp4J3VqNfWAUOO0d1Us'];
const isMale = Math.random() < 0.5;
const voicePool = isMale ? maleVoices : femaleVoices;
const selectedVoiceId = voicePool[Math.floor(Math.random() * voicePool.length)];
const selectedGender = isMale ? 'male' : 'female';

const videoItems = (payload.content_items || []).filter(item =>
  ['instagram','linkedin','youtube','pinterest','facebook','tiktok'].includes(item.platform)
);
const textItems = [];

// Use Instagram item's script as primary voiceover (most engagement-optimised)
const instagramItem = videoItems.find(i => i.platform === 'instagram');
const primaryVideoItem = instagramItem || videoItems[0] || {};
let voiceoverScript = primaryVideoItem.script || payload.script || '';

// PRONUNCIATION FIX: Replace "YFIT" with "Why-Fit" so ElevenLabs pronounces it correctly.
// ElevenLabs reads "YFIT" as "Y-fit" (like the letter Y). "Why-Fit" produces the correct
// "Why-fit" pronunciation. We use a regex to catch all case variants: YFIT, Yfit, yfit.
// We preserve surrounding punctuation and don't replace inside URLs or hashtags.
voiceoverScript = voiceoverScript
  .replace(/\bYFIT\b/g, 'Why-Fit')
  .replace(/\bYfit\b/g, 'Why-Fit')
  .replace(/\byfit\b/g, 'Why-Fit');

return [{
  json: {
    run_date: payload.run_date,
    content_angle: payload.content_angle,
    article_title: payload.article_title || '',
    article_url: payload.article_url || '',
    pexels_query: payload.pexels_query || 'fitness workout gym exercise',
    voice_id: payload.voice_id || selectedVoiceId,
    voice_gender: payload.voice_gender || selectedGender,
    script: voiceoverScript,
    video_items: videoItems,
    text_items: textItems,
    all_items: payload.content_items || [],
    dry_run: payload.dry_run === true,
  }
}];

const supabaseUrl = 'https://mxggxpoxgqubojvumjlt.supabase.co';

// Use the actual Key returned by the Upload Audio node
const uploadData = $('Upload Audio to Supabase Storage').first().json;
const audioKey = uploadData.Key;
if (!audioKey) {
  throw new Error('Upload Audio node did not return a Key. Check the Upload Audio node output.');
}
const audioUrl = `${supabaseUrl}/storage/v1/object/public/${audioKey}`;
console.log('Audio URL (from actual upload Key):', audioUrl);

// Get word timing from ElevenLabs processing node
const elevenData = $('Process ElevenLabs Response').first().json;
const wordTiming = elevenData.word_timing || [];
const audioDuration = elevenData.audio_duration_from_timing;
console.log(`Word timing entries: ${wordTiming.length}, duration: ${audioDuration}s`);

// Get parse data for video/text items, caption, and pexels_query
const parseData = $('Parse Supabase Payload').first().json;
const firstVideoItem = (parseData.video_items || [])[0] || {};
const captionText = ((firstVideoItem.caption || parseData.script || '').split('\n')[0]).substring(0, 60);

// pexels_query: use per-item query if available, fall back to top-level, then content_angle
const pexelsQuery = parseData.pexels_query || parseData.content_angle || 'fitness workout gym';
console.log('Pexels query:', pexelsQuery);

// dry_run: pass through from the original payload
const dryRun = parseData.dry_run === true;
console.log('dry_run:', dryRun);

return [{
  json: {
    ...parseData,
    voiceover_url: audioUrl,
    caption_text: captionText,
    word_timing: wordTiming,
    audio_duration: audioDuration,
    video_items: parseData.video_items,
    text_items: parseData.text_items,
    pexels_query: pexelsQuery,
    dry_run: dryRun,
  }
}];

// Split by Video Platform — v3.7.3
// Changes from v3.7.2:
//   - Fix SyntaxError: replaced literal newlines in CTA_MAP strings with \n escape sequences
// $input is the YouTube no-captions assembly result
const ytResult = $input.first().json;
const mainResult = $('Assemble Video (Railway ffmpeg)').first().json;
if (!mainResult.success || !mainResult.video_url) {
  throw new Error('Main video assembly failed: ' + (mainResult.error || 'No video URL returned'));
}
const youtubeVideoUrl = (ytResult && ytResult.success && ytResult.video_url)
  ? ytResult.video_url
  : mainResult.video_url;
// v3.7.2: SRT URL from YouTube assembly (for Upload-Post subtitles_url)
const srtUrl = (ytResult && ytResult.srt_url) ? ytResult.srt_url : '';
const parseData = $('Parse Supabase Payload').first().json;
const CTA_MAP = {
