  instagram: '\n\n🔗 Link in bio → get your free calorie target',
  youtube: '\n\n⬇️ Get your free calorie target → https://yfitai.com/go?utm_source=youtube&utm_medium=social&utm_campaign=organic#quick-setup',
  linkedin: '\n\n🚀 Get your free calorie target → https://yfitai.com/go?utm_source=linkedin&utm_medium=social&utm_campaign=organic#quick-setup',
  pinterest: '\n\n📌 Get your free calorie target → https://yfitai.com/go?utm_source=pinterest&utm_medium=social&utm_campaign=organic#quick-setup',
  facebook: '\n\n💪 Get your free calorie target — https://yfitai.com/go?utm_source=facebook&utm_medium=social&utm_campaign=organic#quick-setup',
};
const FIRST_COMMENT_MAP = {
  tiktok: '👉 Get your free calorie target → https://yfitai.com/go?utm_source=tiktok&utm_medium=social&utm_campaign=organic#quick-setup',
  instagram: '🔗 Get your free calorie target → https://yfitai.com/go?utm_source=instagram&utm_medium=social&utm_campaign=organic#quick-setup',
  youtube: '⬇️ Get your free calorie target → https://yfitai.com/go?utm_source=youtube&utm_medium=social&utm_campaign=organic#quick-setup',
  linkedin: '🚀 Get your free calorie target → https://yfitai.com/go?utm_source=linkedin&utm_medium=social&utm_campaign=organic#quick-setup',
  pinterest: '📌 Get your free calorie target → https://yfitai.com/go?utm_source=pinterest&utm_medium=social&utm_campaign=organic#quick-setup',
