    : String(hashtagsArr);
  let title = item.title || parseData.content_angle || 'YFIT Fitness Tip';
  if (platform === 'youtube') {
    title = title.substring(0, 100);
  }
  const videoUrl = (platform === 'youtube') ? youtubeVideoUrl : mainResult.video_url;
  return {
    json: {
      platform,
      video_url: videoUrl,
      caption: captionWithCta,
      hashtags: hashtagStr,
      title,
      first_comment: firstComment,
      srt_url: srtUrl,
      run_date: parseData.run_date,
      content_angle: parseData.content_angle,
