  };
});

// Handle Pinterest and LinkedIn text posts
// These don't need video — just text + hashtags via Upload-Post
const parseData = $('Parse Supabase Payload').first().json;

// Platform-specific CTA map (industry-standard for max conversion)
// Research shows: action verb + benefit + URL = highest CTR
const CTA_MAP = {
  linkedin: '

🚀 Get your free calorie target → https://yfitai.com/go?utm_source=linkedin&utm_medium=social&utm_campaign=organic#quick-setup',
  pinterest: '

✨ Get your free calorie target → https://yfitai.com/go?utm_source=pinterest&utm_medium=social&utm_campaign=organic#quick-setup',
};

return (parseData.text_items || []).map(item => {
  const platform = item.platform;
  const baseCta = CTA_MAP[platform] || '\n\n🔗 Learn more at yfitai.com';
  const rawCaption = item.caption || item.script || '';
  const hashtags = (item.hashtags || []).join(' ');

  // Append CTA before hashtags so it's visible without expanding the post
  const captionWithCta = rawCaption.trimEnd() + baseCta;

  return {
    json: {
