});

const SUPABASE_URL = 'https://mxggxpoxgqubojvumjlt.supabase.co';
const SUPABASE_KEY = '<REDACTED_REBIND_EXISTING_CREDENTIAL>';
const items = $input.all();
const results = [];
for (const item of items) {
  const postData = item.json;
  const platform = postData.platform || 'unknown';
  const uploadPostJobId = postData.jobId || postData.job_id || postData.id || null;
  const uploadStatus = postData.error ? 'failed' : (postData.jobId ? 'published' : 'submitted');
  const record = {
    platform: platform,
    content_id: postData.content_id || null,
    upload_post_job_id: uploadPostJobId,
    video_url: postData.video_url || null,
    caption: (postData.caption || '').substring(0, 500),
    status: uploadStatus,
    posted_at: new Date().toISOString(),
    error_message: postData.error || null,
  };
  try {
    const resp = await fetch(`${SUPABASE_URL}/rest/v1/social_posts`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${SUPABASE_KEY}`,
        'apikey': SUPABASE_KEY,
        'Content-Type': 'application/json',
        'Prefer': 'return=representation',
      },
      body: JSON.stringify(record),
    });
    const saved = await resp.json();
    const savedId = saved?.[0]?.id;
    console.log(`[social_posts] ${platform} | status=${uploadStatus} | job=${uploadPostJobId} | HTTP ${resp.status}`);
    results.push({ json: { ...record, db_id: savedId, saved: resp.ok } });
  } catch (err) {
    console.error(`Failed to save to social_posts [${platform}]: ${err.message}`);
    results.push({ json: { ...record, saved: false, error: err.message } });
  }
}
const successCount = results.filter(r => r.json.saved).length;
console.log(`social_posts saved: ${successCount}/${results.length}`);
return results.length > 0 ? results : [{ json: { success: true, posts_saved: 0 } }];

