// Process ElevenLabs /with-timestamps JSON response
// Response: { audio_base64: string, alignment: { characters, character_start_times_seconds, character_end_times_seconds } }

const item = $input.first();
const body = item.json;

if (!body.audio_base64) {
  throw new Error('No audio_base64 in ElevenLabs response. Keys: ' + Object.keys(body).join(', '));
}

// Convert base64 audio to binary buffer for Supabase upload
const audioBuffer = Buffer.from(body.audio_base64, 'base64');

// Build word-level timing from character-level alignment data
const alignment = body.alignment || {};
const chars = alignment.characters || [];
const startTimes = alignment.character_start_times_seconds || [];
const endTimes = alignment.character_end_times_seconds || [];

const words = [];
let currentWord = '';
let wordStart = null;
let wordEnd = null;

for (let i = 0; i < chars.length; i++) {
  const ch = chars[i];
  const t0 = startTimes[i] !== undefined ? startTimes[i] : 0;
  const t1 = endTimes[i] !== undefined ? endTimes[i] : 0;

  if (ch === ' ' || ch === '\n' || ch === '\r') {
    if (currentWord.trim()) {
      words.push({ word: currentWord.trim(), start: wordStart, end: wordEnd });
    }
    currentWord = '';
    wordStart = null;
    wordEnd = null;
  } else {
    if (wordStart === null) wordStart = t0;
    wordEnd = t1;
    currentWord += ch;
  }
}
if (currentWord.trim()) {
  words.push({ word: currentWord.trim(), start: wordStart, end: wordEnd });
}

const audioDuration = words.length > 0 ? words[words.length - 1].end : null;
console.log(`[ElevenLabs] Audio: ${audioBuffer.length} bytes | Words: ${words.length} | Duration: ${audioDuration}s`);

const parseData = $('Parse Supabase Payload').first().json;

return [{
  json: {
    ...parseData,
    word_timing: words,
    audio_duration_from_timing: audioDuration,
  },
  binary: {
    data: {
      data: audioBuffer.toString('base64'),
      mimeType: 'audio/mpeg',
      fileExtension: 'mp3',
      fileName: 'voiceover.mp3'
    }
  }
}];

